import * as THREE from 'three';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
import {RoomEnvironment} from 'three/addons/environments/RoomEnvironment.js';
import {OUTFITS,EXTRAS,HAIR,PLACES,PALETTE,DEFAULT_STATE,sanitizeState,equipOutfit,toggleExtra,randomLook} from './wardrobe-state.js';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const STORAGE='beluga-wardrobe-v1',LOOKS='beluga-looks-v1';
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let state=sanitizeState(read(STORAGE,DEFAULT_STATE));
if(!read(STORAGE,null)&&matchMedia('(prefers-reduced-motion: reduce)').matches)state.gentle=true;
let tab='outfits',selectedExtra='sunglasses',part='primary',character,action=null,yaw=-.13,targetYaw=-.13,soundEnabled=false,audioContext,speechTimer,toastTimer,photoSnapshot;
const blinkMeshes=[];
const materials=new Map(),originalColors=new Map(),joints=new Map();
const savedRaw=read(LOOKS,[]);let looks=Array.isArray(savedRaw)?savedRaw.filter(x=>x&&typeof x==='object'&&x.state).slice(0,24).map(x=>({...x,state:sanitizeState(x.state)})):[];
const base='/'; // All assets are served from the same private Site.
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch{toast('This browser couldn’t save your choices.')}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function say(message){$('#speech').textContent=message;$('#speech').classList.add('visible');clearTimeout(speechTimer);speechTimer=setTimeout(()=>$('#speech').classList.remove('visible'),2600)}
function chime(kind='soft'){
 if(!soundEnabled)return;try{audioContext??=new AudioContext();audioContext.resume();const now=audioContext.currentTime;[523.25,659.25,783.99].slice(0,kind==='soft'?1:3).forEach((frequency,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=frequency;gain.gain.setValueAtTime(0,now+i*.08);gain.gain.linearRampToValueAtTime(.06,now+i*.08+.02);gain.gain.exponentialRampToValueAtTime(.001,now+i*.08+.5);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+i*.08);osc.stop(now+i*.08+.55)})}catch{soundEnabled=false}}
function currentTarget(){return tab==='hair'?'hair':tab==='extras'?selectedExtra:state.outfit}
function currentParts(){return tab==='hair'?[['primary','Hair']]:tab==='extras'?EXTRAS.find(x=>x.id===selectedExtra).parts:OUTFITS.find(x=>x.id===state.outfit).parts}
function renderItems(){
 const list=tab==='outfits'?OUTFITS:tab==='hair'?HAIR:EXTRAS;const box=$('#items');box.replaceChildren();box.setAttribute('aria-labelledby','tab-'+tab);
 for(const item of list){const b=document.createElement('button');b.className='item';b.type='button';b.dataset.id=item.id;const active=tab==='outfits'?state.outfit===item.id:tab==='hair'?state.hair===item.id:state.extras.includes(item.id);b.setAttribute('aria-pressed',String(active));b.setAttribute('aria-label',item.name+(item.description?', '+item.description:''));
 const img=document.createElement('img');img.src=`./assets/thumbnails/${tab}-${item.id}.png`;img.alt='';img.draggable=false;b.append(img);const label=document.createElement('span');label.className='item-label';label.textContent=item.name;b.append(label);b.addEventListener('click',()=>selectItem(item.id));box.append(b)}
 renderColors();
}
function renderColors(){const parts=currentParts();if(!parts.some(([id])=>id===part))part=parts[0][0];const select=$('#color-part');select.replaceChildren();for(const [id,label] of parts){const opt=document.createElement('option');opt.value=id;opt.textContent=label;select.append(opt)}select.value=part;const container=$('#swatches');container.replaceChildren();const value=state.colors[currentTarget()+'_'+part];for(const [label,color] of PALETTE){const button=document.createElement('button');button.className='swatch';button.style.background=color;button.setAttribute('aria-label',label);button.title=label;button.setAttribute('aria-pressed',String(value===color));button.onclick=()=>setColor(color);container.append(button)}const custom=document.createElement('label');custom.className='swatch custom';custom.title='Choose any color';const input=document.createElement('input');input.type='color';input.value=value||'#b4a5d1';input.setAttribute('aria-label','Choose a custom color');input.oninput=()=>setColor(input.value,false);input.onchange=()=>renderColors();custom.append(input);container.append(custom)}
function setColor(color,render=true){state.colors[currentTarget()+'_'+part]=color;applyCharacter();persist();if(render)renderColors()}
function selectItem(id){
 if(tab==='outfits'){state=equipOutfit(state,id);part='primary';applyCharacter();play('dress');say(({base:'There she is ♡',moonlight:'A little moonlight moment ♡',pink:'Ready for a little getaway!',city:'Somewhere lovely to go?',marigold:'I feel like dancing.',ocean:'A little sunshine, please.',weekend:'Shall we go for a walk?'})[id])}
 else if(tab==='hair'){state.hair=id;applyCharacter();play('pose');say('How do I look? ♡')}
 else{state=toggleExtra(state,id);selectedExtra=id;part='primary';applyCharacter();play('pose')}
 persist();renderItems();chime();
}
function switchTab(id){tab=id;part='primary';$$('.tabs button').forEach(b=>{const yes=b.dataset.tab===id;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1});renderItems()}
$$('.tabs button').forEach(b=>{b.onclick=()=>switchTab(b.dataset.tab);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=$$('.tabs button').filter(t=>!t.disabled);let i=tabs.indexOf(b);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length;switchTab(tabs[i].dataset.tab);tabs[i].focus()}});
$('#color-part').onchange=e=>{part=e.target.value;renderColors()};$('#reset-color').onclick=()=>{delete state.colors[currentTarget()+'_'+part];applyCharacter();persist();renderColors();chime()};
let placeRequest=0;
async function setPlace(id,initial=false){if(!PLACES.some(p=>p.id===id))return;const request=++placeRequest;const img=new Image();img.src=`./assets/backgrounds/${id}.png`;try{await img.decode()}catch{toast('That scenery could not load. Try again.');return}if(request!==placeRequest)return;state.place=id;document.documentElement.dataset.theme=id;$('#backdrop').style.backgroundImage=`url("${img.src}")`;$('#place-current').textContent=PLACES.find(p=>p.id===id).name;$$('.place').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===id)));persist();if(!initial)chime();if(renderer)renderer.toneMappingExposure=id==='moonlit'?1.05:1.1;renderAmbient()}
for(const p of PLACES){const b=document.createElement('button');b.className='place';b.dataset.id=p.id;b.title=p.name;b.setAttribute('aria-label',p.name);b.setAttribute('aria-pressed',String(p.id===state.place));b.style.backgroundImage=`url(./assets/backgrounds/${p.id}.png)`;b.onclick=()=>setPlace(p.id);$('#places').append(b)}
function renderAmbient(){$$('.ambient-star').forEach(e=>e.remove());if(!state.sparkles||state.gentle)return;for(let i=0;i<9;i++){const span=document.createElement('span');span.className='ambient-star';span.textContent='✧';span.style.cssText=`left:${12+(i*17)%80}%;top:${10+(i*23)%65}%;animation-delay:${i*.61}s`;$('#particles').append(span)}}
function burst(symbol='♡'){if(state.gentle)return;for(let i=0;i<7;i++){const p=document.createElement('span');p.className='particle';p.textContent=symbol;p.style.cssText=`left:${42+Math.random()*25}%;top:${22+Math.random()*25}%;animation-delay:${i*.09}s`;$('#particles').append(p);setTimeout(()=>p.remove(),2900)}}
function play(type){if(!character)return;action={type,start:performance.now()/1000};if(type==='twirl'){action.yaw=targetYaw;chime('happy')}if(type==='kiss'){say('This one’s for you ♡');burst();chime('happy')}if(type==='wiggle'){say('A very good day for a wiggle!');burst('✧');chime('happy')}if(type==='boop'){say('Boop! You found my happy button.');burst();chime('happy')}}
$$('[data-action]').forEach(b=>b.onclick=()=>play(b.dataset.action));$('#surprise').onclick=()=>{state=randomLook(state);applyCharacter();renderItems();persist();play('dress');say('A little surprise, just for you.');chime('happy')};
$('#sound').onclick=()=>{soundEnabled=!soundEnabled;$('#sound').setAttribute('aria-pressed',String(soundEnabled));$('#sound').setAttribute('aria-label',soundEnabled?'Turn sound off':'Turn sound on');$('.sound-off').hidden=soundEnabled;chime('happy')};
$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$('#settings-button').onclick=()=>{$('#gentle-motion').checked=state.gentle;$('#sparkles').checked=state.sparkles;$('#settings-dialog').showModal()};$('#gentle-motion').onchange=e=>{state.gentle=e.target.checked;persist();renderAmbient()};$('#sparkles').onchange=e=>{state.sparkles=e.target.checked;persist();renderAmbient()};$('#reset-view').onclick=()=>{targetYaw=-.13;toast('Back to your lovely self.');$('#settings-dialog').close()};
$('#save-look').onclick=()=>{if(!character)return;const look={id:crypto.randomUUID(),name:OUTFITS.find(x=>x.id===state.outfit).name,date:new Date().toISOString(),state:structuredClone(state)};looks.unshift(look);looks=looks.slice(0,24);try{localStorage.setItem(LOOKS,JSON.stringify(looks));toast('Your look is saved ♡');chime('happy')}catch{toast('This browser couldn’t save your look.')}};
function renderLooks(){const list=$('#saved-list');list.replaceChildren();if(!looks.length){const p=document.createElement('p');p.className='empty-looks';p.textContent='A favorite outfit belongs here. Try “Save look”.';list.append(p);return}for(const look of looks){const row=document.createElement('div');row.className='saved-row';const img=document.createElement('img');img.src=`./assets/thumbnails/outfits-${look.state.outfit}.png`;img.alt='';row.append(img);const meta=document.createElement('div');meta.className='saved-meta';const title=document.createElement('strong');title.textContent=look.name;const sub=document.createElement('small');sub.textContent=PLACES.find(p=>p.id===look.state.place).name;meta.append(title,sub);row.append(meta);const wear=document.createElement('button');wear.textContent='Wear';wear.onclick=()=>{state=sanitizeState(look.state);applyCharacter();setPlace(state.place);renderItems();persist();$('#saved-dialog').close();play('pose')};const del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label','Remove saved '+look.name);del.onclick=()=>{looks=looks.filter(l=>l.id!==look.id);try{localStorage.setItem(LOOKS,JSON.stringify(looks))}catch{}renderLooks()};row.append(wear,del);list.append(row)}}
$('#saved-button').onclick=()=>{renderLooks();$('#saved-dialog').showModal()};

const canvas=$('#viewport');let renderer,scene,camera,mixer,clock;let backgroundPhoto;
function applyCharacter(){if(!character)return;character.traverse(o=>{if(o.name.startsWith('Outfit_'))o.visible=o.name==='Outfit_'+state.outfit;if(o.name.startsWith('Extra_'))o.visible=state.extras.includes(o.name.slice(6));if(o.name.startsWith('Hair_'))o.visible=o.name==='Hair_'+state.hair;if(o.name.startsWith('WeekendSleeve'))o.visible=state.outfit==='weekend'});for(const [name,list] of materials){const color=state.colors[name];for(const mat of list)mat.color.copy(color?new THREE.Color(color):originalColors.get(mat.uuid))}$('#pose-label').textContent=OUTFITS.find(x=>x.id===state.outfit).name}
function rotate(delta){targetYaw+=delta}$('#rotate-left').onclick=()=>rotate(-.4);$('#rotate-right').onclick=()=>rotate(.4);canvas.onkeydown=e=>{if(e.key==='ArrowLeft'){e.preventDefault();rotate(-.2)}if(e.key==='ArrowRight'){e.preventDefault();rotate(.2)}if(e.key.toLowerCase()==='b')play('boop')};
let pointer=null;canvas.onpointerdown=e=>{pointer={x:e.clientX,y:e.clientY,last:e.clientX,moved:false};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!pointer)return;if(Math.hypot(e.clientX-pointer.x,e.clientY-pointer.y)>5)pointer.moved=true;if(pointer.moved){targetYaw+=(e.clientX-pointer.last)*.009;action=null}pointer.last=e.clientX};canvas.onpointerup=e=>{if(pointer&&!pointer.moved&&character){const r=canvas.getBoundingClientRect();const pos=new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);const ray=new THREE.Raycaster();ray.setFromCamera(pos,camera);const hit=ray.intersectObject(character,true).find(h=>{let o=h.object;while(o){if(!o.visible)return false;o=o.parent}return true});if(hit){const local=character.worldToLocal(hit.point.clone());play(local.y>2.7?'boop':'pose')}}pointer=null};canvas.onpointercancel=()=>pointer=null;
function joint(name,x=0,y=0,z=0){const j=joints.get(name);if(j){j.rotation.set(j.userData.rest.x+x,j.userData.rest.y+y,j.userData.rest.z+z)}}
function animate(ms){const t=ms/1000;if(!renderer)return;requestAnimationFrame(animate);if(document.hidden)return;const delta=clock.getDelta();if(mixer)mixer.update(Math.min(delta,.05));if(character){const amp=state.gentle?.15:1;const elapsed=action?t-action.start:0;let bounce=0,tilt=Math.sin(t*.8)*.016*amp,headTilt=Math.sin(t*.67)*.027*amp,armL=Math.sin(t*1.15)*.022*amp,armR=-Math.sin(t*1.15+.4)*.022*amp;
 if(action){const p=Math.min(elapsed/2.3,1),wave=Math.sin(p*Math.PI);switch(action.type){case'twirl':yaw=action.yaw+Math.PI*2*(p*p*(3-2*p));targetYaw=yaw;bounce=Math.sin(p*Math.PI)*.12*amp;armL=-wave*.3;armR=wave*.3;break;case'wiggle':tilt=Math.sin(p*Math.PI*8)*.085*wave*amp;armL=-.25*wave;armR=.25*wave;bounce=Math.abs(Math.sin(p*Math.PI*4))*.06*amp;break;case'kiss':headTilt=-.1*wave*amp;armR=.5*wave;break;case'boop':headTilt=.1*Math.sin(p*Math.PI*3)*wave*amp;bounce=.045*wave*amp;break;case'dress':case'pose':headTilt=-.08*wave*amp;armL=-.25*wave;armR=.12*wave;break}if(p>=1)action=null}
 yaw+=(targetYaw-yaw)*.1;character.rotation.y=yaw;character.rotation.z=tilt;character.position.y=bounce;joint('Head',0,0,headTilt);joint('ArmL',0,0,armL);joint('ArmR',0,0,armR);const blink=(t%4.7);const closure=blink<.18?Math.sin(blink/.18*Math.PI):0;for(const mesh of blinkMeshes){for(const name of ['Blink_L','Blink_R']){const index=mesh.morphTargetDictionary[name];if(index!==undefined)mesh.morphTargetInfluences[index]=closure}}for(const n of ['EyeL','EyeR']){const eye=joints.get(n);if(eye)eye.scale.y=blink<.14?Math.max(.06,Math.abs(blink-.07)/.07):1}}
 renderer.render(scene,camera)}
async function init3D(){try{renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;scene=new THREE.Scene();const pmrem=new THREE.PMREMGenerator(renderer);const environment=new RoomEnvironment();scene.environment=pmrem.fromScene(environment,.04).texture;environment.dispose();pmrem.dispose();scene.add(new THREE.HemisphereLight(0xfff0dd,0x8b7fa0,2.1));const key=new THREE.DirectionalLight(0xffe7d2,3.2);key.position.set(-3,5,4);scene.add(key);const fill=new THREE.DirectionalLight(0xd4ddff,1.4);fill.position.set(3,3,-2);scene.add(fill);camera=new THREE.PerspectiveCamera(31,1,.01,100);camera.position.set(0,2.25,8.1);camera.lookAt(0,2.05,0);clock=new THREE.Clock();const resize=()=>{const r=canvas.parentElement.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.position.z=camera.aspect<.8?10:8.1;camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(canvas.parentElement);resize();
 const gltf=await new GLTFLoader().loadAsync('./assets/models/beluga.glb');character=gltf.scene;scene.add(character);character.traverse(o=>{if(o.isMesh){if(o.morphTargetDictionary?.Blink_L!==undefined)blinkMeshes.push(o);o.frustumCulled=false;const list=Array.isArray(o.material)?o.material:[o.material];for(const m of list){if(!m.color)continue;if(!originalColors.has(m.uuid))originalColors.set(m.uuid,m.color.clone());const key=m.name.replace(/\.\d+$/,'');if(!materials.has(key))materials.set(key,[]);if(!materials.get(key).includes(m))materials.get(key).push(m)}}const jointName=o.name.replace(/\.\d+$/,'');if(['Head','ArmL','ArmR','EyeL','EyeR'].includes(jointName)){o.userData.rest=o.rotation.clone();joints.set(jointName,o)}});applyCharacter();$('#loading').hidden=true;requestAnimationFrame(animate);setTimeout(()=>say('Oh, there you are ♡'),800);
 }catch(error){console.error(error);$('#loading').classList.add('error');$('#loading').replaceChildren();const p=document.createElement('p');p.textContent='Our little beluga couldn’t load.';const b=document.createElement('button');b.textContent='Try again';b.onclick=()=>location.reload();$('#loading').append(p,b)}}
function drawCover(ctx,img,w,h){const scale=Math.max(w/img.width,h/img.height);ctx.drawImage(img,(w-img.width*scale)/2,(h-img.height*scale)/2,img.width*scale,img.height*scale)}
$('#photo').onclick=async()=>{if(!character)return;try{const bg=new Image();bg.src=`./assets/backgrounds/${state.place}.png`;await bg.decode();const out=document.createElement('canvas');out.width=1200;out.height=1200;const c=out.getContext('2d');drawCover(c,bg,1200,1200);renderer.render(scene,camera);const h=1160,w=h*canvas.width/canvas.height;c.drawImage(canvas,(1200-w)/2,-20,w,h);photoSnapshot=out;$('#photo-preview').src=out.toDataURL('image/png');$('#photo-caption').value='';$('#photo-dialog').showModal();chime()}catch{toast('The photo couldn’t be made. Please try again.')}};
$('#download-photo').onclick=()=>{if(!photoSnapshot)return;const out=document.createElement('canvas');out.width=1200;out.height=1280;const c=out.getContext('2d');c.fillStyle='#fff8ef';c.fillRect(0,0,1200,1280);c.drawImage(photoSnapshot,24,24,1152,1152);c.fillStyle='#6a4b65';c.font='28px Georgia';c.textAlign='center';c.fillText($('#photo-caption').value||'A little moment with you ♡',600,1230,1120);out.toBlob(blob=>{if(!blob)return;const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download='beluga-little-keepsake.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},'image/png')};
renderItems();setPlace(state.place,true);init3D();
